-- Supabase PostgreSQL. Apply via npm run db:migrate using the server-only database URL.
-- Entity payloads use JSONB; stable IDs, unique expression indexes, checks and foreign keys
-- enforce ownership and revision invariants. The Express API authorizes each request.
-- No application data is accessible through Supabase's public REST API.
CREATE TABLE IF NOT EXISTS public.profiles (id text PRIMARY KEY CHECK (id ~ '^[a-f0-9]{24}$'), data jsonb NOT NULL CHECK (jsonb_typeof(data)='object'));
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles FROM PUBLIC;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON public.profiles FROM anon, authenticated; END IF; END $$;
CREATE INDEX IF NOT EXISTS profiles_created ON public.profiles ((data->>'createdAt') DESC, id DESC);
