CREATE INDEX IF NOT EXISTS ideas_search ON public.ideas USING gin (to_tsvector('simple', coalesce(data->>'title','') || ' ' || coalesce(data->>'pitch','') || ' ' || coalesce(data->>'tags','')));
-- Generated keys let JSONB entities retain SQL foreign-key guarantees.
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS user_id text GENERATED ALWAYS AS (data->>'userId') STORED UNIQUE;
ALTER TABLE public.visitor_sessions ADD COLUMN IF NOT EXISTS userid_ref text GENERATED ALWAYS AS (data->>'userId') STORED REFERENCES public.profiles(user_id);
ALTER TABLE public.ideas ADD COLUMN IF NOT EXISTS authorid_ref text GENERATED ALWAYS AS (data->>'authorId') STORED REFERENCES public.profiles(user_id);
ALTER TABLE public.roasts ADD COLUMN IF NOT EXISTS authorid_ref text GENERATED ALWAYS AS (data->>'authorId') STORED REFERENCES public.profiles(user_id);
ALTER TABLE public.roasts ADD COLUMN IF NOT EXISTS ideaid_ref text GENERATED ALWAYS AS (data->>'ideaId') STORED REFERENCES public.ideas(id);
ALTER TABLE public.idea_revisions ADD COLUMN IF NOT EXISTS ideaid_ref text GENERATED ALWAYS AS (data->>'ideaId') STORED REFERENCES public.ideas(id);
ALTER TABLE public.replies ADD COLUMN IF NOT EXISTS roastid_ref text GENERATED ALWAYS AS (data->>'roastId') STORED REFERENCES public.roasts(id);
ALTER TABLE public.improvements ADD COLUMN IF NOT EXISTS ideaid_ref text GENERATED ALWAYS AS (data->>'ideaId') STORED REFERENCES public.ideas(id);
ALTER TABLE public.milestones ADD COLUMN IF NOT EXISTS ideaid_ref text GENERATED ALWAYS AS (data->>'ideaId') STORED REFERENCES public.ideas(id);
ALTER TABLE public.collaborations ADD COLUMN IF NOT EXISTS ideaid_ref text GENERATED ALWAYS AS (data->>'ideaId') STORED REFERENCES public.ideas(id);
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='profile_role') THEN ALTER TABLE public.profiles ADD CONSTRAINT profile_role CHECK (data->>'role' IN ('member','admin')); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='visitor_hash') THEN ALTER TABLE public.visitor_sessions ADD CONSTRAINT visitor_hash CHECK (data->>'tokenHash' ~ '^[a-f0-9]{64}$' AND data->>'expiresAt' IS NOT NULL); END IF;
IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='idea_state') THEN ALTER TABLE public.ideas ADD CONSTRAINT idea_state CHECK (data->>'status' IN ('draft','published','archived') AND data->>'visibility' IN ('public','unlisted')); END IF;
END $$;
-- Better Auth is used only by private moderator accounts. Members need no signup.
CREATE TABLE IF NOT EXISTS public."user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE IF NOT EXISTS public.verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public."rateLimit" (id text PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL DEFAULT 0, "lastRequest" bigint NOT NULL);
CREATE INDEX IF NOT EXISTS rt_session_user_idx ON public.session("userId");
CREATE INDEX IF NOT EXISTS verification_identifier ON public.verification(identifier);
